def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if expr == "A":
            result.append(expr)
        elif expr == "A & (A | B)":
            result.append("A")
        elif expr == "A | (A & B)":
            result.append("A")
        elif expr == "A & (~A | B)":
            result.append(expr + " & B")
        elif expr == "A | (~A & B)":
            result.append(expr + " | B")
        else:
            result.append(expr)
    return result

