def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """

    def python2_tzname(*args, **kwargs):
        # Call the original tzname function
        decorate = namefunc(*args, **kwargs)
        if not isinstance(decorate, bytes):
            # If the output is not bytes, encode it to bytes
            return decorate.encode('utf-8')
        return decorate

    return python2_tzname

