def deep_merge_nodes(nodes):
    result = {}
    seen = set()

    def merge_values(node1, node2):
        if isinstance(node1, ruamel.yaml.nodes.MappingNode) and isinstance(node2, ruamel.yaml.nodes.MappingNode):
            return ruamel.yaml.nodes.MappingNode(tag=node2.tag, value=[(k, mergeValues(v1, v2)) for k, v1 in node1 if k not in node2 or v1 != v2 and k in seen])
        elif isinstance(node1, ruamel.yaml.nodes.MultipleValueNode) and isinstance(node2, ruamel.yaml.nodes.MultipleValueNode):
            return ruamel.yaml.nodes.MultipleValueNode(tag=node2.tag, value=set(node1.value) | set(node2.value) - seen)
        else:
            return node2 if node2 not in seen else node1

    for key, value in nodes:
        if key in result:
            result[key] = merge_values(result[key], value)
        else:
            result[key] = value
            seen.add(key)

    return list(zip(result.keys(), result.values()))

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parser_dict = {parser.name: parser for parser in subparsers}
    result = {}
    remaining_args = []

    for arg in unparsed_arguments:
        for parser_name, parser in parser_dict.items():
            args, remaining_args = parser.parse_known_args(arg, namespace=result.get(parser_name, argparse.Namespace()))
            if args:
                result[parser_name] = args
                break

    return result, remaining_args

def deep_merge_nodes(nodes):
