def size_to_bytes(size: str) -> int:
    size_match = re.match(r'(\d+[A-Za-z]+)', size)
    if not size_match:
        raise ValueError("Invalid input format")
    number = int(size_match.group(1))
    unit = size_match.group(2)

    unit_map = {
        'B': 1,
        'KB': 1024,
        'MB': 1024 ** 2,
        'GB': 1024 ** 3,
        'TB': 1024 ** 4
    }

    if unit not in unit_map:
        raise ValueError("Unrecognized file size unit")
    return number * unit_map[unit]

