def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number < 0:
        return '-' + int_to_string(-number, alphabet)
    if number == 0:
        return alphabet[0]
    result = []
    while number > 0:
        result.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)
    if padding is not None and len(result) < padding:
        result = ['0'] * (padding - len(result)) + result
    return ''.join(result)

