def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    split_frequency = frequency.split()
    if len(split_frequency) != 2:
        raise ValueError("Invalid frequency format")

    amount = int(split_frequency[0])
    unit = split_frequency[1]

    if unit == "weeks":
        return datetime.timedelta(weeks=amount)
    elif unit == "days":
        return datetime.timedelta(days=amount)
    elif unit == "hours":
        return datetime.timedelta(hours=amount)
    elif unit == "minutes":
        return datetime.timedelta(minutes=amount)
    elif unit == "seconds":
        return datetime.timedelta(seconds=amount)
    else:
        raise ValueError("Unsupported unit")

def make_find_paths(find_paths):
    result = []
    pattern = r"\w+:/"
    for path in find_paths:
        if re.match(pattern, path):
            result.append(path)
        else:
            patterns = []
            for part in path.split('/'):
                if part != '':
                    patterns.append(part)
            result.append(f"sh:**/*{'*/'.join(patterns)}*/**")
    return result

