    if not parsed.scheme or not parsed.hostname or not parsed.netloc:
        raise ValueError("Invalid image href")
    image_id = parsed.path
    if '.' in image_id:
        image_id = image_id.split('.')[0]
    use_ssl = parsed.scheme == 'https'
