def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    metadata_path = os.path.join(plugin_dir, 'metadata.json')
    plugin_meta_data = {}

    if not os.path.exists(metadata_path):
        return plugin_meta_data

    try:
        with open(metadata_path, 'r') as file:
            plugin_meta_data = json.load(file)
    except json.JSONDecodeError as e:
        return plugin_meta_data

    flat_dict = {}
    for key, value in plugin_meta_data.items():
        if isinstance(value, dict):
            nested_dict = get_plugin_spec_flatten_dict(value)
            flat_dict.update(nested_dict)
        else:
            flat_dict[key] = value

    return flat_dict

